}]}]}, {"position": 2, "max_points": 5, "label": "Comment prenez-vous une décision proportionnée sur l''accès de ce festivalier à cet événement ?", "hint": "Cette décision doit tenir compte tant de la dangerosité objective de cet objet que du contexte global de cette découverte pour rester proportionnée.", "perfect": "Je retiens cet objet en expliquant clairement les raisons de cette rétention, cette mesure restant proportionnée compte tenu de la nature de cet objet dans le contexte d''un rassemblement de cette ampleur.\n\nJe lui propose des solutions pratiques pour la suite de sa soirée, comme une consigne extérieure ou une restitution différée de cet objet, ces alternatives restant utiles pour ne pas simplement lui refuser l''accès à cet événement.\n\nJe reste attentive à ne pas le sanctionner disproportionnément pour ce qui semble relever d''un oubli plausible, cette mesure de rétention restant suffisante sans nécessiter d''autre conséquence.\n\nJe consigne les circonstances de cette découverte, cette documentation restant utile pour le suivi du dispositif de sécurité de cet événement.", "points": [{"position": 1, "label": "Retenir cet objet en expliquant clairement les raisons", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : mesure proportionnée au contexte du rassemblement.", "groups": [{"position": 1, "keywords": ["objet retenu", "raisons expliquées", "mesure proportionnée"]}]}, {"position": 2, "label": "Proposer des solutions pratiques comme une consigne extérieure", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Alternatives évitant un simple refus d''accès.", "groups": [{"position": 1, "keywords": ["solutions pratiques", "consigne extérieure", "alternative au refus"]}]}, {"position": 3, "label": "Ne pas sanctionner disproportionnément un oubli plausible", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rétention suffisante sans autre conséquence.", "groups": [{"position": 1, "keywords": ["pas de sanction disproportionnée", "oubli plausible", "rétention suffisante"]}]}, {"position": 4, "label": "Consigner les circonstances de cette découverte", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Documentation utile pour le dispositif de sécurité.", "groups": [{"position": 1, "keywords": ["circonstances consignées", "dispositif de sécurité", "documentation utile"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment communiquez-vous cette décision de manière à préserver un climat serein pour la suite du filtrage ?", "hint": "Cette décision doit être communiquée de manière à ne pas créer de tension inutile, tant pour ce festivalier que pour les autres personnes qui suivent dans la file de filtrage.", "perfect": "Je communique ma décision de manière calme et posée, cette approche restant appropriée pour ne pas créer de tension inutile avec ce festivalier qui a fourni une explication plausible.\n\nJe reste attentive à ne pas dramatiser cette situation face aux autres personnes présentes dans la file, ce cas restant un incident mineur qui ne doit pas ralentir excessivement le reste du filtrage.\n\nJe reste courtoise dans l''ensemble de cet échange, cette attitude professionnelle restant importante pour préserver l''ambiance festive de cet événement malgré cette découverte.\n\nJe m''assure que cette décision soit appliquée de manière cohérente avec les autres découvertes similaires, cette équité de traitement restant essentielle pour la crédibilité du dispositif de sécurité.", "points": [{"position": 1, "label": "Communiquer la décision de manière calme et posée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : pas de tension inutile avec une explication plausible.", "groups": [{"position": 1, "keywords": ["communication calme", "décision posée", "explication plausible"]}]}, {"position": 2, "label": "Ne pas dramatiser cette situation face aux autres dans la file", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Incident mineur ne ralentissant pas le filtrage.", "groups": [{"position": 1, "keywords": ["pas de dramatisation", "incident mineur", "filtrage préservé"]}]}, {"position": 3, "label": "Rester courtoise pour préserver l''ambiance festive de l''événement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Attitude professionnelle malgré cette découverte.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "ambiance festive", "attitude professionnelle"]}]}, {"position": 4, "label": "S''assurer d''une application cohérente avec les autres découvertes similaires", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Équité de traitement pour la crédibilité du dispositif.", "groups": [{"position": 1, "keywords": ["cohérence assurée", "équité de traitement", "crédibilité du dispositif"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-supporters-tensions-avant-match', '{"slug": "ordre-supporters-tensions-avant-match", "title": "Deux groupes se font face de part et d''autre du parvis", "theme_slug": "ordre-public", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 17 heures. Aux abords d''un stade avant le début d''un match, vous constatez que deux groupes de supporters rivaux se font face de part et d''autre du parvis, cette confrontation imminente se déroulant dans un lieu où de nombreux tiers, notamment des familles venues assister paisiblement à cet événement sportif, se trouvent également présents et potentiellement exposés à un affrontement qui semble sur le point de se déclencher. Cette situation de tension palpable entre ces deux groupes constitués nécessite une action rapide pour prévenir ce risque de confrontation directe avant qu''elle ne dégénère en violence effective.\n\nCette configuration, où la priorité doit être donnée à la prévention de cet affrontement plutôt qu''à sa seule gestion après qu''il se soit déclenché, impose une intervention qui vise avant tout à maintenir une séparation physique claire entre ces deux groupes rivaux.\n\nCette situation nécessite de maintenir cette séparation physique tout en rendant compte sans délai de cette situation à risque élevé, cette double exigence restant essentielle pour prévenir efficacement ce danger tout en s''assurant du soutien nécessaire face à cette configuration potentiellement dangereuse.", "questions": [{"position": 1, "max_points": 5, "label": "Comment maintenez-vous la séparation physique entre ces deux groupes rivaux pour prévenir cet affrontement imminent ?", "hint": "La priorité doit être donnée à la prévention de cette confrontation par le maintien d''une séparation physique claire, cette action préventive restant plus efficace qu''une gestion après le déclenchement de la violence.", "perfect": "Je me positionne, avec mes collègues présents, de manière à maintenir une séparation physique claire entre ces deux groupes, cette interposition restant la priorité immédiate face à ce risque de confrontation.\n\nJe reste attentive aux mouvements de chacun de ces groupes, cette vigilance permettant d''anticiper toute tentative de rapprochement qui pourrait précipiter cet affrontement redouté.\n\nJe sollicite sans délai un renfort suffisant pour maintenir efficacement cette séparation, cette configuration à deux groupes nombreux nécessitant probablement davantage de moyens que ceux immédiatement disponibles.\n\nJe reste attentive à sécuriser en priorité les tiers présents, notamment ces familles qui pourraient se retrouver prises entre ces deux groupes en cas de dégradation soudaine de la situation.", "points": [{"position": 1, "label": "Se positionner pour maintenir une séparation physique claire", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : interposition comme priorité immédiate.", "groups": [{"position": 1, "keywords": ["séparation physique", "interposition prioritaire", "confrontation évitée"]}]}, {"position": 2, "label": "Rester attentive aux mouvements de chacun des groupes", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Anticiper toute tentative de rapprochement.", "groups": [{"position": 1, "keywords": ["mouvements surveillés", "rapprochement anticipé", "vigilance continue"]}]}, {"position": 3, "label": "Solliciter sans délai un renfort suffisant", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Moyens supplémentaires nécessaires face à deux groupes nombreux.", "groups": [{"position": 1, "keywords": ["renfort sollicité", "moyens supplémentaires", "groupes nombreux"]}]}, {"position": 4, "label": "Sécuriser en priorité les tiers présents comme les familles", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Protection face à une dégradation soudaine.", "groups": [{"position": 1, "keywords": ["tiers sécurisés", "familles protégées", "dégradation anticipée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment rendez-vous compte sans délai de cette situation à risque élevé pour obtenir le soutien nécessaire ?", "hint": "Cette configuration dangereuse nécessite une remontée d''information rapide et précise pour permettre l''engagement des moyens appropriés face à ce risque de confrontation.", "perfect": "Je transmets sans délai à ma hiérarchie la gravité de cette situation, notamment la présence de ces deux groupes constitués et le risque imminent d''affrontement que je constate.\n\nJe précise avec exactitude le nombre approximatif de personnes impliquées dans chacun de ces groupes, cette information étant essentielle pour dimensionner correctement la réponse à apporter.\n\nJe signale également la présence de nombreux tiers sur ce parvis, cette information sur les personnes potentiellement exposées devant orienter l''urgence de la réponse à engager.\n\nJe reste disponible pour fournir toute information complémentaire nécessaire, cette réactivité restant importante pour permettre une décision rapide et adaptée à cette situation à risque élevé.", "points": [{"position": 1, "label": "Transmettre sans délai la gravité et le risque d''affrontement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : deux groupes constitués et risque imminent.", "groups": [{"position": 1, "keywords": ["gravité transmise", "groupes constitués", "risque imminent"]}]}, {"position": 2, "label": "Préciser le nombre approximatif de personnes dans chaque groupe", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information essentielle pour dimensionner la réponse.", "groups": [{"position": 1, "keywords": ["nombre précisé", "dimensionnement", "réponse adaptée"]}]}, {"position": 3, "label": "Signaler la présence de nombreux tiers exposés", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Information orientant l''urgence de la réponse.", "groups": [{"position": 1, "keywords": ["tiers signalés", "personnes exposées", "urgence orientée"]}]}, {"position": 4, "label": "Rester disponible pour toute information complémentaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactivité pour une décision rapide et adaptée.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "décision rapide", "réactivité importante"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous les tiers présents sur ce parvis pendant que cette tension persiste entre ces deux groupes ?", "hint": "Ces familles et autres tiers présents méritent une attention particulière pour les éloigner ou les protéger de ce risque de confrontation qui pourrait se déclencher rapidement.", "perfect": "Je recherche activement à éloigner ou à diriger les familles et autres tiers présents vers des zones plus sûres, cette protection restant prioritaire face au risque de confrontation entre ces deux groupes.\n\nJe communique clairement aux personnes concernées les raisons de cette invitation à s''éloigner, cette transparence permettant une meilleure coopération de leur part face à cette situation tendue.\n\nJe reste attentive à ne pas créer de panique disproportionnée par mon intervention, cette gestion devant rester mesurée tout en assurant efficacement la sécurité de ces tiers présents.\n\nJe coordonne cette mise en sécurité avec mes collègues présents, cette action collective restant nécessaire pour couvrir efficacement l''ensemble de ce parvis fréquenté par de nombreuses personnes.", "points": [{"position": 1, "label": "Rechercher à éloigner les familles et tiers vers des zones plus sûres", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : protection prioritaire face au risque de confrontation.", "groups": [{"position": 1, "keywords": ["familles éloignées", "zones sûres", "protection prioritaire"]}]}, {"position": 2, "label": "Communiquer clairement les raisons de cette invitation à s''éloigner", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Transparence permettant une meilleure coopération.", "groups": [{"position": 1, "keywords": ["raisons communiquées", "transparence apportée", "coopération facilitée"]}]}, {"position": 3, "label": "Ne pas créer de panique disproportionnée par son intervention", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Gestion mesurée assurant la sécurité.", "groups": [{"position": 1, "keywords": ["pas de panique", "gestion mesurée", "sécurité assurée"]}]}, {"position": 4, "label": "Coordonner cette mise en sécurité avec les collègues présents", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Action collective couvrant l''ensemble du parvis.", "groups": [{"position": 1, "keywords": ["coordination collective", "parvis couvert", "action coordonnée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-contre-manifestation-proximite', '{"slug": "ordre-contre-manifestation-proximite", "title": "Les deux cortèges vont se croiser dans dix minutes", "theme_slug": "ordre-public", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 14 heures. Vous êtes positionnée en centre-ville où deux cortèges portant des revendications radicalement opposées progressent selon des trajectoires qui les amèneront à se croiser dans une dizaine de minutes à peine, cette proximité imminente entre ces deux camps aux positions antagonistes exigeant de votre part une impartialité absolue dans la gestion de cette situation particulièrement sensible sur le plan politique. Cette configuration, où votre propre neutralité personnelle se trouve mise à l''épreuve par la nature contradictoire des messages portés par ces deux cortèges, nécessite un comportement et des propos qui ne laissent transparaître aucune préférence pour l''un ou l''autre de ces camps opposés.\n\nCette exigence de neutralité politique, essentielle à la légitimité de votre intervention dans ce type de situation sensible, impose une vigilance particulière sur l''ensemble de votre attitude, tant dans vos gestes que dans vos éventuels échanges avec les participants de chacun de ces deux cortèges.\n\nCette situation nécessite de maintenir cette neutralité stricte dans votre comportement et vos propos tout au long de cette gestion de la proximité entre ces deux cortèges, cette rigueur étant essentielle pour préserver la légitimité de votre intervention face à ces deux camps opposés.", "questions": [{"position": 1, "max_points": 5, "label": "Comment maintenez-vous une neutralité stricte dans votre comportement face à ces deux cortèges aux positions opposées ?", "hint": "Cette neutralité absolue doit se manifester dans l''ensemble de votre attitude, cette exigence étant essentielle face à la sensibilité politique de cette confrontation potentielle.", "perfect": "Je maintiens une attitude rigoureusement identique envers chacun de ces deux cortèges, cette égalité de traitement restant essentielle pour ne laisser transparaître aucune préférence personnelle.\n\nJe reste attentive à mes propres réactions et expressions non verbales, ces éléments pouvant trahir involontairement une opinion personnelle que je dois impérativement garder pour moi dans ce cadre professionnel.\n\nJe m''abstiens de tout commentaire sur le fond des revendications portées par l''un ou l''autre de ces cortèges, cette réserve restant nécessaire indépendamment de mes propres convictions personnelles sur ces sujets.\n\nJe reste factuelle et professionnelle dans mes éventuels échanges avec les participants de chacun de ces groupes, cette rigueur relationnelle étant essentielle pour préserver ma crédibilité auprès des deux camps.", "points": [{"position": 1, "label": "Maintenir une attitude rigoureusement identique envers les deux cortèges", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : égalité de traitement sans préférence transparente.", "groups": [{"position": 1, "keywords": ["attitude identique", "égalité de traitement", "pas de préférence"]}]}, {"position": 2, "label": "Rester attentive à ses propres réactions et expressions non verbales", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Éviter de trahir involontairement une opinion personnelle.", "groups": [{"position": 1, "keywords": ["réactions maîtrisées", "expressions contrôlées", "opinion non trahie"]}]}, {"position": 3, "label": "S''abstenir de tout commentaire sur le fond des revendications", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Réserve indépendante des convictions personnelles.", "groups": [{"position": 1, "keywords": ["pas de commentaire", "réserve maintenue", "convictions personnelles écartées"]}]}, {"position": 4, "label": "Rester factuelle et professionnelle dans les échanges avec les participants", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Rigueur relationnelle préservant la crédibilité.", "groups": [{"position": 1, "keywords": ["échanges factuels", "professionnalisme", "crédibilité préservée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment organisez-vous concrètement la gestion de cette proximité imminente entre ces deux cortèges ?", "hint": "Au-delà de la seule neutralité, une organisation concrète reste nécessaire pour gérer ce risque de croisement entre deux cortèges aux positions radicalement opposées.", "perfect": "Je transmets sans délai à ma hiérarchie cette proximité imminente, cette information étant essentielle pour permettre l''engagement rapide des moyens nécessaires à la gestion de ce risque.\n\nJe recherche avec mes collègues présents les possibilités concrètes de maintenir une séparation physique entre ces deux cortèges, cette interposition restant nécessaire pour éviter tout contact direct entre ces positions antagonistes.\n\nJe reste attentive à l''évolution de la trajectoire de chacun de ces cortèges, cette surveillance continue permettant d''ajuster en temps réel la réponse à apporter à cette situation évolutive.\n\nJe coordonne cette gestion avec l''ensemble des effectifs présents, cette action collective restant nécessaire face à l''ampleur de cette configuration à haut risque.", "points": [{"position": 1, "label": "Transmettre sans délai cette proximité imminente à la hiérarchie", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : engagement rapide des moyens nécessaires.", "groups": [{"position": 1, "keywords": ["proximité transmise", "moyens engagés", "urgence signalée"]}]}, {"position": 2, "label": "Rechercher les possibilités de maintenir une séparation physique", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Interposition évitant tout contact direct.", "groups": [{"position": 1, "keywords": ["séparation physique", "interposition nécessaire", "contact direct évité"]}]}, {"position": 3, "label": "Rester attentive à l''évolution de la trajectoire de chaque cortège", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Surveillance continue ajustant la réponse en temps réel.", "groups": [{"position": 1, "keywords": ["trajectoire surveillée", "réponse ajustée", "situation évolutive"]}]}, {"position": 4, "label": "Coordonner cette gestion avec l''ensemble des effectifs présents", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Action collective face à l''ampleur du risque.", "groups": [{"position": 1, "keywords": ["coordination collective", "effectifs présents", "ampleur du risque"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment communiquez-vous avec chacun de ces deux cortèges de manière équitable durant cette gestion de proximité ?", "hint": "Cette communication équitable reste essentielle pour préserver la confiance des deux camps dans l''impartialité de votre intervention durant cette situation sensible.", "perfect": "Je communique de manière strictement identique avec les représentants de chacun de ces deux cortèges, cette égalité de traitement restant essentielle pour préserver la confiance des deux camps.\n\nJe transmets les mêmes informations pratiques à chacun de ces groupes concernant les mesures prises pour gérer cette proximité, cette transparence équitable évitant tout soupçon de favoritisme.\n\nJe reste attentive à ne pas passer plus de temps ou d''attention avec l''un de ces cortèges au détriment de l''autre, cette vigilance sur l''équilibre de mon temps restant importante pour cette impartialité.\n\nJe documente avec précision cette gestion équitable de la situation, cette transparence pouvant s''avérer utile si l''un des deux camps venait à questionner ultérieurement l''impartialité de cette intervention.", "points": [{"position": 1, "label": "Communiquer de manière strictement identique avec les deux cortèges", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : préserver la confiance des deux camps.", "groups": [{"position": 1, "keywords": ["communication identique", "confiance préservée", "deux camps"]}]}, {"position": 2, "label": "Transmettre les mêmes informations pratiques à chacun des groupes", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Transparence équitable évitant tout soupçon de favoritisme.", "groups": [{"position": 1, "keywords": ["informations identiques", "transparence équitable", "favoritisme évité"]}]}, {"position": 3, "label": "Ne pas passer plus de temps avec l''un des cortèges au détriment de l''autre", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance sur l''équilibre du temps consacré.", "groups": [{"position": 1, "keywords": ["temps équilibré", "vigilance maintenue", "impartialité"]}]}, {"position": 4, "label": "Documenter précisément cette gestion équitable de la situation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Utile si l''impartialité était questionnée ultérieurement.", "groups": [{"position": 1, "keywords": ["gestion documentée", "impartialité questionnée", "transparence utile"]}]}]}]}'::jsonb);